-- IT Transformation Hub — migration 07: IT Asset master data (from the asset register Excel)
-- Target DB: it-hub   Run as: root_admin (Query Tool on it-hub). Safe to run more than once:
-- a value is only added if the same label does not already exist in that category.
BEGIN;

-- asset_type

-- asset_status

-- asset_license_type

-- asset_license_status

-- asset_location

-- asset_os

-- department

-- vendor

COMMIT;

SELECT category, count(*) FROM public.masters WHERE category IN ('asset_type','asset_status','asset_license_type','asset_license_status','asset_location','asset_os','department','vendor') GROUP BY category ORDER BY category;
